SELECT CASE WHEN EXISTS (
           SELECT 1
             FROM T_FAULT_MANAGEMENT
            WHERE TERM_GROUP_ID    = #{termGroupId}
              AND TERM_ID          = #{termId}
              AND FAULT_CLASS_CD   = #{faultClassCd}
              AND PROVIDER_TYPE_CD = #{providerType}
              AND VENDOR_CD        = #{providerCd}
              AND CALL_DATE        >=  #{fromDate}
              AND FAULT_STATUS IN ('O','P')   
       ) THEN 1 ELSE 0 END
  FROM DUAL

SELECT ERR_NAME
  FROM T_ERROR_MESSAGE
 WHERE ERR_GROUP_CD = #{errGroupCd}
   AND ERR_CD       = #{errCd}
FETCH FIRST 1 ROWS ONLY

