          LAST_ATM_CALL_DATE      = #{jnlDate}
        , LAST_ATM_CALL_TIME      = #{jnlTime}
        , LAST_ATM_SNO            = #{faultSeq}
        , LAST_ATM_FAULT_CLASS_CD = #{faultClassCd}


          LAST_OUT_CALL_DATE      = #{jnlDate}
        , LAST_OUT_CALL_TIME      = #{jnlTime}
        , LAST_OUT_SNO            = #{faultSeq}
        , FAULT_CLASS_CD          = #{faultClassCd}



WHERE TERM_GROUP_ID = #{termGroupId}
  AND TERM_ID       = #{termId}
